#!/usr/bin/env python3 -I
"""Team scores for dual meets from per-opponent placings: ours = sum of Cloverleaf FullPoints per placing (a relay is one row, so it counts once); possible = 9 per scored individual event + 5 per relay event
(events = those the meet has results for, per gender; seated excluded); opponent = possible - ours (assumes every scoring place was filled, true when the sheets say 'X possible').
Validates the formula against every official MeetTeamResults row, then writes insert-only SQL for the rest. usage: dual_scores.py <out.sql>"""
import os, sys, collections
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from places_lib import q, esc
rows = q("""SELECT m.Id, m.Name, CONVERT(varchar(10), m.Date, 120), e.Gender, mp.MeetParticipantId, s.Name, mp.FullPoints, mp.SplitPoints, p.AthleteId, e.Name, e.Id
FROM MeetPlacings mp JOIN Performances p ON p.Id=mp.PerformanceId JOIN Events e ON e.Id=p.EventId JOIN Meets m ON m.Id=mp.MeetId
JOIN MeetParticipants x ON x.Id=mp.MeetParticipantId JOIN Schools s ON s.Id=x.SchoolId WHERE mp.MeetParticipantId IS NOT NULL AND e.Name NOT LIKE 'Seated%'""")
ours = collections.defaultdict(float)
relplaced_by = collections.defaultdict(set)
evname = {}
scored_ind = collections.defaultdict(set)   # (meet, gender, opponent) -> individual events with a placing (an unscored event, e.g. pole vault 'do not score', has none)
for mid, mn, md, g, part, sch, full, split, aid, en, eid in rows:
    ours[(int(mid), int(g), sch)] += float(full)
    evname[int(eid)] = en
    (scored_ind if aid not in ('NULL', None) else relplaced_by)[(int(mid), int(g), sch)].add(int(eid))   # relay rows hold the team's points in FullPoints (SplitPoints is the per-member share)
events = collections.defaultdict(lambda: [set(), set()])   # (meet, gender) -> [individual event ids, relay event ids]
for mid, g, en, eid, aid in q("SELECT p.MeetId, e.Gender, e.Name, e.Id, ISNULL(p.AthleteId,0) FROM Performances p JOIN Events e ON e.Id=p.EventId WHERE p.ResultStatus=0 AND e.Name NOT LIKE 'Seated%' AND p.MeetId IN (SELECT DISTINCT MeetId FROM MeetPlacings WHERE MeetParticipantId IS NOT NULL)"):
    events[(int(mid), int(g))][1 if int(aid) == 0 else 0].add(int(eid))
official = {(int(m), int(g), sch): (float(a), float(b)) for m, g, sch, a, b in q("SELECT r.MeetId, r.Gender, s.Name, r.OurScore, r.OpponentScore FROM MeetTeamResults r JOIN MeetParticipants x ON x.Id=r.OpponentMeetParticipantId JOIN Schools s ON s.Id=x.SchoolId WHERE r.Deleted=0 AND r.OurScore IS NOT NULL")}
names = {int(m): (n, d) for m, n, d in q("SELECT Id, Name, CONVERT(varchar(10), Date, 120) FROM Meets")}
lines = ["-- Generated by scripts/places/dual_scores.py: dual team scores computed from per-opponent placings (see BRAIN.md C113). Insert-only; Id-independent.", "SET QUOTED_IDENTIFIER ON;", "SET XACT_ABORT ON;", "BEGIN TRANSACTION;", "DECLARE @m INT, @mp INT;"]
bad = 0; n = 0; chk = 0
for (mid, g, sch), o in sorted(ours.items()):
    ind, rel = events[(mid, g)]
    placed = scored_ind[(mid, g, sch)]
    pv = {e for e in ind if evname.get(e) == 'Pole Vault'}
    missing = [evname.get(e, e) for e in (ind - pv) - placed]
    possible = 9 * len(ind - pv) + 9 * len(pv & placed) + 5 * len(rel)   # every held event awards its points; no placing = 0 for us
    # full = every non-PV individual event with a Cloverleaf performance has a placing for this opponent, and the relays are all placed
    full_ok = not missing and rel <= relplaced_by[(mid, g, sch)]
    if pv - placed: full_ok = False; missing = ['Pole Vault (scored or not? no placings)']
    opp = possible - o
    if (mid, g, sch) in official:
        oa, ob = official[(mid, g, sch)]; chk += 1
        if abs(oa - o) > 0.02 or abs(ob - opp) > 0.02:
            bad += 1; print(f"  MISMATCH vs official {names[mid][0]} g{g} {sch}: official {oa:g}-{ob:g}, computed {o:g}-{opp:g} (possible {possible})")
        continue
    if False and not full_ok:   # owner: score every meet that has placings (a missing placing means 0 points)
        print(f"  SKIP (placings incomplete: {missing or 'relays'}) {names[mid][0]} g{g} vs {sch}"); continue
    n += 1; mn, md = names[mid]
    print(f"  {mn} {'Boys' if g == 1 else 'Girls'} vs {sch}: CLO {o:g} - {opp:g} (possible {possible})")
    lines.append(f"SET @m = (SELECT TOP 1 Id FROM Meets WHERE Name=N'{esc(mn)}' AND CAST(Date AS date)='{md}');")
    lines.append(f"SET @mp = (SELECT TOP 1 mp.Id FROM MeetParticipants mp JOIN Schools s ON s.Id=mp.SchoolId WHERE mp.MeetId=@m AND s.Name=N'{esc(sch)}' AND mp.Deleted=0);")
    lines.append(f"IF @m IS NOT NULL AND @mp IS NOT NULL AND NOT EXISTS (SELECT 1 FROM MeetTeamResults WHERE MeetId=@m AND Gender={g} AND OpponentMeetParticipantId=@mp AND Deleted=0) INSERT INTO MeetTeamResults (MeetId, Gender, OpponentMeetParticipantId, OurScore, OpponentScore, Place, FieldSize) VALUES (@m, {g}, @mp, {round(o, 2)}, {round(opp, 2)}, NULL, NULL);")
lines += ["COMMIT TRANSACTION;", f"-- {n} computed team results"]
open(sys.argv[1], 'w').write('\n'.join(lines) + '\n'); print(f"{chk} official rows checked, {bad} mismatches; {n} to insert")
